        address
    ) external view returns (Pool memory);

    function batchHarvestMarketRewards(address[] calldata _markets, uint256 minEthToRecieve) external;

    function harvestMarketReward(address _market, address _caller, uint256 _minEthRecive) external;

    // PendleRouterV4
    enum SwapType {
        NONE,
        KYBERSWAP,
        ONE_INCH,
        ETH_WETH
    }

    struct SwapData {
        SwapType swapType;
        address extRouter;
        bytes extCalldata;
        bool needScale;
    }

    struct TokenInput {
        address tokenIn;
        uint256 netTokenIn;
        address tokenMintSy;
        address pendleSwap;
        SwapData swapData;
    }

    function addLiquiditySingleTokenKeepYt(
        address receiver,
