        console.log("MKR %s", IERC20(MKR).balanceOf(address(this)) / 1e18);
        console.log("SNX %s", IERC20(SNX).balanceOf(address(this)) / 1e18);
        console.log("SUSHI %s", IERC20(SUSHI).balanceOf(address(this)) / 1e18);
    }
