        borrow(1);
    }

    function borrow(uint256 num) internal {
        address pool = pools[num-1];
        uint256 borrowAmount = borrowAmounts[num-1];
        if (borrowAmount == 0) {
            borrowAmount = IERC20(BSC_USD).balanceOf(pool);
            borrowAmounts[num-1] = borrowAmount;
